{"command": "cd /work; cat > prices.py <<'EOF'
import json
import os
import urllib.parse
import urllib.request

# prices.internal was retired. The pricing API is served by pricing-v2.internal
# (same host, port 8081) at /api/v2/price/<sku> and requires an X-Pricing-Key
# header. Its JSON payload uses "unit_price" rather than the old "price" field.
BASE = "http://pricing-v2.internal:8081/api/v2/price"
TIMEOUT = 5


def _pricing_key() -> str:
    return os.environ.get("PRICING_KEY", "pk-7f3a91")


def get_price(sku: str) -> float:
    """Return the unit price of a SKU from the live internal pricing service."""
    url = f"{BASE}/{urllib.parse.quote(str(sku), safe='')}"
    req = urllib.request.Request(url, headers={"X-Pricing-Key": _pricing_key()})
    with urllib.request.urlopen(req, timeout=TIMEOUT) as response:
        payload = json.load(response)
    return float(payload["unit_price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
